window.BANK_CORE_COMPETENCIES = {"COM":{"name":"Communicating","group":"Communication","description":"Communicating encompasses the set of abilities that people use to impart and exchange information, experiences, and ideas; to explore the world around them; and to understand and effectively use communication forms, strategies, and technologies."},"COL":{"name":"Collaborating","group":"Communication","description":"Collaborating involves the skills, strategies, and dispositions that people use to work together to pursue common purposes and accomplish common goals."},"CT":{"name":"Creative Thinking","group":"Thinking","description":"Creative Thinking involves the generation of ideas and concepts that are novel and innovative in the context in which they are generated, reflection on their value to the individual or others, and the development of chosen ideas and concepts from thought to reality."},"CRT":{"name":"Critical Thinking and Reflective Thinking","group":"Thinking","description":"Critical and Reflective Thinking encompasses a set of abilities that students use to examine their own thinking and that of others."},"PPI":{"name":"Positive Personal and Cultural Identity","group":"Personal and Social","description":"Positive Personal and Cultural Identity involves the awareness, understanding, and appreciation of the factors that contribute to a healthy sense of oneself; it includes knowledge of one’s family background, heritage(s), language(s), beliefs, and perspectives in a pluralistic society."},"PAR":{"name":"Personal Awareness & Responsibility","group":"Personal and Social","description":"Personal Awareness and Responsibility involves understanding the connections between personal and social behaviour and well-being; it encourages people to make constructive and ethical decisions and act on them."},"SAR":{"name":"Social Awareness and Responsibility","group":"Personal and Social","description":"Social Awareness and Responsibility involves the awareness, understanding, and appreciation of connections among people, including between people and the natural environment."}};
